        :listeners="{ search: (value: string) => (lastSearch = value) }"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>collapsedWidth</code> / <code>height</code> / <code>radius</code> 是滑杆，
